   168	                    throw new Xjs44Exception("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
   169	                }
   170	            } catch (Xbf54Exception e) {
   171	                throw e;
   172	            } catch (Exception e) {
   173	                throw new Xjs44Exception("결제 정보 조회 중 오류가 발생했습니다.", e);
   174	            }
   177	            Map<String, Object> response;
   178	            try {
   179	                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
   180	            } catch (Xbf54Exception e) {
   181	                throw e;
   182	            } catch (Exception e) {
   183	                throw new Xbf54ApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
   184	            }
